#include <iostream>

int main()
{
    int highest{ 0 };
    int score{};
    std::cin >> score;

    while (score != -1)
    {
        if (score > highest)
        {
            highest = score;
        }
        std::cin >> score;
    }

    std::cout << "Highest: " << highest << '\n';
    return 0;
}
